using System; using System.IO; using System.Net; using System.Net.Sockets; using System.Net.Security; using System.Security.Authentication; using Basalt.Core; using Basalt.Windows;
class SplitTunRegression {
 static int Port(){var l=new TcpListener(IPAddress.Loopback,0);l.Start();int p=((IPEndPoint)l.LocalEndpoint).Port;l.Stop();return p;}
 static void Request(IPAddress ip,string host) {using(var c=new TcpClient(ip.AddressFamily)){var pending=c.BeginConnect(ip,443,null,null);if(!pending.AsyncWaitHandle.WaitOne(10000))throw new TimeoutException("TCP timeout");c.EndConnect(pending);c.ReceiveTimeout=10000;c.SendTimeout=10000;using(var ssl=new SslStream(c.GetStream(),false)){ssl.AuthenticateAsClient(host,null,(SslProtocols)3072,false);var b=System.Text.Encoding.ASCII.GetBytes("GET / HTTP/1.1\r\nHost: "+host+"\r\nConnection: close\r\n\r\n");ssl.Write(b);var reader=new StreamReader(ssl);string line=reader.ReadLine();if(line==null||!line.StartsWith("HTTP/1."))throw new Exception("No HTTP response");}}}
 static int Main(){string root=AppDomain.CurrentDomain.BaseDirectory;using(var log=new StreamWriter(Path.Combine(root,"split-tun-result.txt"),false)){log.AutoFlush=true;try {
 var stored=new SettingsStore(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Basalt","settings.dat"),new WindowsSecrets()).Load();var original=ProviderRouting.Resolve(stored.Profiles.Find(p=>p.Id==stored.SelectedId)??stored.Profiles[0],stored);
 if(original.ProviderFormat!="happ")throw new Exception("Test expects Happ policy");var ip=Array.Find(Dns.GetHostAddresses("2ip.ru"),a=>a.AddressFamily==AddressFamily.InterNetwork);var control=Array.Find(Dns.GetHostAddresses("example.com"),a=>a.AddressFamily==AddressFamily.InterNetwork);
 var s=new Settings{TunMode=true,BypassLan=false,ProxyPort=Port(),HttpPort=Port(),BridgePort=Port(),NativeBridgePort=Port()};CoreCatalog.Configure(s); CoreCatalog.Verify();
 var profile=Subscriptions.ParseUri("vless://11111111-1111-1111-1111-111111111111@127.0.0.1:"+Port()+"?security=none#Unreachable-test");profile.ProviderFormat="happ";profile.ProviderConfig=original.ProviderConfig;profile.RouteAssetDirectory=original.RouteAssetDirectory;
 using(var runtime=new CoreRuntime(Path.Combine(root,"split-tun-runtime"))) {for(int mode=0;mode<4;mode++){if(mode==2){profile=Subscriptions.ParseUri("hysteria2://unreachable@127.0.0.1:"+Port()+"?sni=example.com#Unreachable-native");profile.ProviderFormat="happ";profile.ProviderConfig=original.ProviderConfig;profile.RouteAssetDirectory=original.RouteAssetDirectory;}if(mode%2==1){var policy=Json.Read(original.ProviderConfig);policy["DirectSites"]=new string[0]; policy["DirectIp"]=new[]{"geoip:ru",ip.ToString()+"/32"}; var hosts=policy.ContainsKey("DnsHosts")?ProviderRouting.Map(policy["DnsHosts"]):Json.Obj(); hosts["2ip.ru"]=ip.ToString();policy["DnsHosts"]=hosts;profile.ProviderConfig=Json.Write(policy);}runtime.Start(profile,s);try {Request(ip,"2ip.ru");log.WriteLine("PASS 2ip.ru HTTPS with unreachable VPN / "+profile.Protocol+" / "+(mode%2==0?"original provider policy":"IP rules only, domain rules removed, deterministic DNS"));bool failed=false;try{Request(control,"example.com");}catch{failed=true;}if(!failed)throw new Exception("Negative control bypassed VPN unexpectedly");log.WriteLine("PASS unmatched domain cannot use unreachable VPN");}finally{runtime.Stop();}}}
 log.WriteLine("PASS split TUN and cleanup");return 0;
 }catch(Exception e){log.WriteLine("FAIL "+e.GetType().Name+": "+e.Message);return 1;}}}
}
